import re

LINE = re.compile(r'^\s*(?P<line>\d+)(?: (?P<address>[0-9A-Fa-f]{8})(?: (?P<data><[^>]*>|[0-9A-Fa-f()\[\]]+-?))?)?(?:\s+(?P<source>\S.*?))?\s*$')
SEC = re.compile(r'^(?:section|segment)\s+(\S+)', re.I)

def parse(lines):
    rows = []
    used = []
    sec = ''
    for i, l in enumerate(lines):
        if not l.strip():
            continue
        m = LINE.match(l)
        if not m:
            continue
        src = m.group('source') or ''
        s = SEC.match(src)
        if s and not m.group('address'):
            sec = s.group(1)
        rows.append({
            'Line': m.group('line'),
            'section': sec,
            'Address': m.group('address') or '',
            'Data': m.group('data') or '',
            'Source': src,
        })
        used.append(i)
    return {'blocks': [{'name': 'listing', 'kind': 'table', 'lines': used, 'records': rows}], 'skip': []}
